examples.code:
MonarchTextField(
    value = note,
    onValueChange = { note = it },
    modifier = Modifier.appendTextContextMenuComponents {
        if (!note.selection.collapsed) {
            separator()
            item(key = "comment", label = "Comment") {
                comment = note.text.substring(note.selection.min, note.selection.max)
                close()
            }
        }
    },
    label = "Note",
    singleLine = false,
)

MonarchTextField(
    value = text,
    onValueChange = { text = it },
    modifier = Modifier.appendTextContextMenuComponents {
        separator()
        item(key = "bold", label = "Bold") { applied = "bold"; close() }
        item(key = "italic", label = "Italic") { applied = "italic"; close() }
    },
    label = "Title",
)
